// Run with the fixtures generated by scripts/generate-fixtures.py.
const {chromium}=require(process.env.PLAYWRIGHT_MODULE || 'playwright');
const assert=require('node:assert/strict');
const root=process.env.FIXTURES || '/tmp/cuebook-fixtures';
(async()=>{
const browser=await chromium.launch({channel:'chrome',headless:true});const page=await browser.newPage({viewport:{width:1440,height:1100}});
const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('dialog',d=>d.accept());
await page.addInitScript(()=>{window.started=0;window.terminated=0;window.revoked=0;const Old=Worker;window.Worker=class extends Old {constructor(...a){super(...a);window.started++;}terminate(){window.terminated++;super.terminate();}set onmessage(cb){super.onmessage=e=>{const delay=window.workerDelay||0;setTimeout(()=>cb(e),delay);};}};const revoke=URL.revokeObjectURL;URL.revokeObjectURL=(u)=>{window.revoked++;revoke(u);};});
await page.goto(process.env.CUEBOOK_URL||'http://127.0.0.1:5173/automate-somesh/');
const ready=()=>page.waitForFunction(()=>!document.querySelector('#cancel-analysis'));
const saved=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('cuebook-v1')));
const library=()=>page.getByRole('navigation').getByRole('button',{name:'Find your cues',exact:true}).click();
await page.locator('[data-mode="offset"]').click();
await page.locator('[data-upload]').first().setInputFiles(`${root}/score.wav`);await ready();
assert.equal(await page.locator('#analyze').isDisabled(),true);
await page.locator('[data-field="offset"]').fill('01:00:00:00');await page.locator('[data-field="offset"]').dispatchEvent('change');
assert.equal(await page.locator('#analyze').isEnabled(),true);
await page.locator('[data-track]').click();
await page.locator('[data-field="title"]').fill('Retained title');await page.locator('[data-field="title"]').dispatchEvent('change');
await page.locator('[data-mode="manual"]').click();await page.locator('[data-add-cue]').click();
await page.locator('.credit-details summary').click();
await page.locator('[data-field="first"]').fill('Saved composer');await page.locator('[data-field="first"]').dispatchEvent('change');
await library();
assert.equal(await page.locator('#analyze').count(),0);
await page.locator('[data-clear-results="manual"]').click();assert.equal((await saved()).cues.length,0);await page.locator('#undo-clear').click();assert.equal((await saved()).cues.length,1);
await page.locator('[data-mode="offset"]').click();const tracks=(await saved()).tracks;
await page.locator('#analyze').click();await ready();const count=(await saved()).cues.length;assert.ok(count>1);
assert.equal(await page.locator('#analyze').textContent(),'Restart detection');
await page.locator('#analyze').click();await ready();assert.equal((await saved()).cues.length,count);
await page.locator('[data-clear-results="offset"]').click();assert.equal((await saved()).cues.length,1);assert.deepEqual((await saved()).tracks,tracks);
await page.locator('#undo-clear').click();assert.equal((await saved()).cues.length,count);
await page.evaluate(()=>window.workerDelay=800);
await page.locator('#analyze').click();await page.locator('#analyze').click();await ready();assert.equal((await saved()).cues.length,count);
await page.locator('#analyze').click();await page.locator('#cancel-analysis').click();await page.waitForTimeout(1000);assert.equal((await saved()).cues.length,count);
await page.locator('#analyze').click();await page.locator('[data-clear-results="offset"]').click();await page.waitForTimeout(1000);assert.equal((await saved()).cues.length,1);
assert.deepEqual((await saved()).tracks,tracks);
await page.screenshot({path:'/tmp/cuebook-lifecycle.png',fullPage:true});
await page.reload();assert.equal((await saved()).cues.length,1);assert.equal(await page.locator('#analyze').isDisabled(),true);assert.match(await page.locator('#detection-help').textContent(),/Reattach/);
await page.locator('[data-track]').click();await page.locator('[data-reattach]').setInputFiles(`${root}/score.wav`);await ready();
await page.locator('[data-remove-track]').click();assert.equal((await saved()).tracks.length,0);assert.equal((await saved()).cues.length,0);assert.equal(await page.evaluate(()=>window.revoked),1);
await page.reload();assert.equal(await page.locator('[data-track]').count(),0);assert.equal(await page.locator('#analyze').count(),0);
assert.deepEqual(errors,[]);
console.log('PASS lifecycle: per-track removal/last track/revocation/reload; scoped clear+undo; manual cues preserved; repeat/restart/cancel/late callbacks; metadata retained; missing-audio disabled');
await page.locator('[data-mode="movie"]').click();
await page.locator('#movie-upload').setInputFiles(`${root}/movie.mp4`);await ready();
await page.locator('[data-upload]').first().setInputFiles(`${root}/cue-a.wav`);await ready();
await page.locator('#analyze').click();await ready();
const movieState=await saved();assert.ok(movieState.cues.length>0);
await page.locator('#analyze').click();await ready();assert.equal((await saved()).cues.length,movieState.cues.length);
await page.locator('[data-clear-results="movie"]').click();assert.equal((await saved()).cues.length,0);assert.deepEqual((await saved()).movieMetadata,movieState.movieMetadata);
await page.locator('#analyze').click();await ready();assert.equal((await saved()).cues.length,movieState.cues.length);
await page.setViewportSize({width:390,height:844});assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);
assert.deepEqual(errors,[]);
console.log('PASS movie: repeat replaces, clear keeps movie metadata/upload, rerun works, mobile has no overflow');
await browser.close();
})();
